"use client";
import { RecordTable } from "@/components/entity-record-table";
/* eslint-disable react-hooks/set-state-in-effect -- synchronise asynchronous inventory reads with active filters and tab changes. */

import { EntityListWorkspace, EntityListPanel, EntityFormPanel, entitySaveComplete, useWorkspaceSelection, useEntityRecord, routeEntityEdit } from "@/components/entity-list-panel";
import { FormSaveActions } from "@/components/form-save-actions";
import { Fragment, useCallback, useEffect, useState } from "react";
import { Activity, ArrowRightLeft, Boxes, Check, ClipboardCheck, History, Loader2, PackageSearch, Plus, RefreshCw, Search, SlidersHorizontal, Truck, Wand2 } from "lucide-react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select } from "@/components/ui/select";
import { formatPlatformDate, formatPlatformDateTime } from "@/lib/date-time";
import { formatNPR } from "@/lib/catalog";
import { requestSiteConfirmation } from "@/lib/confirmation-events";
import {
  adjustInventoryDepartment,
  cancelInventoryStockCount,
  cancelInventoryTransfer,
  createAdminPurchaseOrder,
  createInventoryStockCount,
  createInventoryOpeningStock,
  createInventoryTransfer,
  dispatchInventoryTransfer,
  finalizeInventoryStockCount,
  getInventoryAlternatives,
  getInventoryMovements,
  getInventoryOverview,
  getInventoryProductMaster,
  getProductRacks,
  getInventoryStockCounts,
  getInventorySuggestions,
  getInventoryTransfers,
  getInventoryVelocity,
  receiveInventoryTransfer,
  updateInventoryProductMaster,
  updateInventoryNearExpiryDays,
  updateInventoryStockCountLines,
  type AdminBranch,
  type InventoryDepartmentRow,
  type InventoryAlternative,
  type InventoryMovement,
  type InventoryOverview,
  type InventoryProductMaster,
  type ProductRack,
  type InventoryStockCount,
  type InventorySuggestion,
  type InventoryTransfer,
  type InventoryVelocity,
} from "@/services/api";

type View = "stock" | "opening-stock" | "master" | "movements" | "suggestions" | "velocity" | "counts" | "transfers";
export type InventoryDepartmentView = View;

const statusTone = (status: string) => status === "IN_STOCK" ? "default" : status === "NEAR_EXPIRY" || status === "LOW_STOCK" ? "secondary" : "destructive";

export function InventoryDepartmentPanel({ token, superAdmin, branchId, branches, canWrite, canManageMaster, canCreatePurchaseDraft, initialView = "stock", setupTitle }: { token: string; superAdmin: boolean; branchId?: string; branches: AdminBranch[]; canWrite: boolean; canManageMaster: boolean; canCreatePurchaseDraft: boolean; initialView?: InventoryDepartmentView; setupTitle?: string }) {
  const [view, setView] = useWorkspaceSelection<View>("inventory", initialView);
  const [filter, setFilter] = useState("");
  const [search, setSearch] = useState("");
  const [nearExpiryDays, setNearExpiryDays] = useState("");
  const [page, setPage] = useState(1);
  const [overview, setOverview] = useState<InventoryOverview | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [selected, setSelected] = useState<InventoryDepartmentRow | null>(null);
  const [delta, setDelta] = useState("");
  const [reason, setReason] = useState("");
  const [adjustmentType, setAdjustmentType] = useState("ADJUSTMENT");
  const [masterRows, setMasterRows] = useState<InventoryProductMaster[]>([]);
  const [rackRows, setRackRows] = useState<ProductRack[]>([]);
  const [master, setMaster] = useState<InventoryProductMaster | null>(null);
  const [masterSearch, setMasterSearch] = useState("");
  const [movements, setMovements] = useState<InventoryMovement[]>([]);
  const [movementProductId, setMovementProductId] = useState("");
  const [movementType] = useState(setupTitle === "Open Stock List" ? "OPENING_STOCK" : "");
  const [suggestions, setSuggestions] = useState<InventorySuggestion[]>([]);
  const [velocity, setVelocity] = useState<InventoryVelocity[]>([]);
  const [velocityDays, setVelocityDays] = useState("90");
  const [velocityFilter, setVelocityFilter] = useState("");
  const [counts, setCounts] = useState<InventoryStockCount[]>([]);
  const [countLines, setCountLines] = useState<{ lineId: string; inventoryId: string; product: string; batchNumber: string; storageLocation?: string; baseUnit: string; unitCost?: number | null; systemQuantity: number; physicalQuantity: string }[]>([]);
  const [activeCount, setActiveCount] = useState("");
  const [transferRows, setTransferRows] = useState<InventoryTransfer[]>([]);
  const [transferSource, setTransferSource] = useState("");
  const [transferTarget, setTransferTarget] = useState("");
  const [transferQuantity, setTransferQuantity] = useState("1");
  const [transferNote, setTransferNote] = useState("");
  const [alternativeKey, setAlternativeKey] = useState("");
  const [alternatives, setAlternatives] = useState<InventoryAlternative[] | null>(null);
  const [alternativesMatchable, setAlternativesMatchable] = useState(true);
  const [alternativesLoading, setAlternativesLoading] = useState(false);
  const [openingProductId, setOpeningProductId] = useState("");
  const [openingBatch, setOpeningBatch] = useState("");
  const [openingQuantity, setOpeningQuantity] = useState("1");
  const [openingPurchasePrice, setOpeningPurchasePrice] = useState("");
  const [openingManufactured, setOpeningManufactured] = useState("");
  const [openingExpiry, setOpeningExpiry] = useState("");
  const [openingReference, setOpeningReference] = useState("");
  const [openingReason, setOpeningReason] = useState("");

  const loadOverview = useCallback(async () => {
    setLoading(true); setError("");
    try {
      const result = await getInventoryOverview(token, { branchId, filter: filter || undefined, search: search || undefined, nearExpiryDays: Number(nearExpiryDays) || undefined, page, pageSize: 100 }, superAdmin);
      setOverview(result);
      if (!nearExpiryDays) setNearExpiryDays(String(result.nearExpiryDays));
    }
    catch (e) { setError(e instanceof Error ? e.message : "Inventory could not be loaded."); }
    finally { setLoading(false); }
  }, [branchId, filter, nearExpiryDays, page, search, superAdmin, token]);

  const loadAuxiliary = useCallback(async () => {
    try {
      if (view === "master" || view === "opening-stock") {
        const [products, racks] = await Promise.all([getInventoryProductMaster(token, masterSearch || undefined, superAdmin, branchId), getProductRacks(token, undefined, superAdmin)]);
        setMasterRows(products); setRackRows(racks.filter((rack) => rack.isActive));
      }
      if (view === "movements" || view === "opening-stock") {
        setMovements(await getInventoryMovements(token, { branchId, productId: movementProductId || undefined, type: movementType || undefined }, superAdmin));
        if (!masterRows.length) setMasterRows(await getInventoryProductMaster(token, undefined, superAdmin));
      }
      if (view === "suggestions") setSuggestions(await getInventorySuggestions(token, branchId, superAdmin));
      if (view === "velocity") setVelocity((await getInventoryVelocity(token, branchId, Number(velocityDays) || 90, velocityFilter || undefined, superAdmin)).rows);
      if (view === "counts") setCounts(await getInventoryStockCounts(token, branchId, superAdmin));
      if (view === "transfers") setTransferRows(await getInventoryTransfers(token, branchId, superAdmin));
    } catch (e) { setError(e instanceof Error ? e.message : "The inventory view could not be loaded."); }
  }, [branchId, masterRows.length, masterSearch, movementProductId, movementType, superAdmin, token, velocityDays, velocityFilter, view]);

  useEffect(() => { void loadOverview(); }, [loadOverview]);
  useEffect(() => { void loadAuxiliary(); }, [loadAuxiliary]);

  const rows = overview?.rows ?? [];
  const countsByStatus = overview?.summary;
  const canTransfer = canWrite && branches.filter((x) => x.isActive && x.id !== branchId).length > 0;

  async function saveAdjustment() {
    if (!selected || Number(delta) === 0 || !reason.trim()) return toast.error("Choose a batch, enter a non-zero quantity and give a reason.");
    try { await adjustInventoryDepartment(token, { inventoryId: selected.id, quantityDelta: Number(delta), reason: reason.trim(), type: adjustmentType }, superAdmin); toast.success("Stock adjustment posted to the movement ledger."); setSelected(null); setDelta(""); setReason(""); await loadOverview();  entitySaveComplete(); }
    catch (e) { toast.error(e instanceof Error ? e.message : "The stock adjustment could not be saved."); }
  }

  async function saveOpeningStock() {
    const product = masterRows.find((row) => row.id === openingProductId);
    const selectedBranch = branchId || branches.find((row) => row.isActive)?.id;
    const quantity = Number(openingQuantity);
    const purchasePrice = Number(openingPurchasePrice || product?.purchaseRate || 0);
    if (!product || !selectedBranch || !openingBatch.trim() || !Number.isInteger(quantity) || quantity <= 0 || purchasePrice < 0 || !openingReason.trim()) return toast.error("Choose an active product and branch, batch, positive quantity, purchase rate and reason.");
    try {
      await createInventoryOpeningStock(token, { productId: product.id, branchId: selectedBranch, quantity, batchNumber: openingBatch.trim(), purchasePrice, manufacturingDate: openingManufactured || undefined, expiryDate: openingExpiry || undefined, reference: openingReference.trim() || undefined, reason: openingReason.trim() }, superAdmin);
      toast.success(`Opening stock posted for ${product.name}; the batch is now in the inventory ledger.`);
      setOpeningBatch(""); setOpeningQuantity("1"); setOpeningPurchasePrice(""); setOpeningManufactured(""); setOpeningExpiry(""); setOpeningReference(""); setOpeningReason("");
      await Promise.all([loadOverview(), loadAuxiliary()]);
     entitySaveComplete(); } catch (e) { toast.error(e instanceof Error ? e.message : "Opening stock could not be posted."); }
  }

  async function saveNearExpiryDefault() {
    const days = Number(nearExpiryDays);
    if (![30, 60, 90, 180].includes(days)) return toast.error("Choose a 30, 60, 90 or 180 day threshold.");
    try {
      await updateInventoryNearExpiryDays(token, days, superAdmin);
      toast.success(`The platform near-expiry alert threshold is now ${days} days.`);
      await loadOverview();
     entitySaveComplete(); } catch (e) { toast.error(e instanceof Error ? e.message : "The near-expiry setting could not be saved."); }
  }

  async function toggleAlternatives(row: InventoryDepartmentRow) {
    const key = `${row.productId}:${row.branchId}`;
    if (alternativeKey === key) { setAlternativeKey(""); return; }
    setAlternativeKey(key); setAlternatives(null); setAlternativesLoading(true);
    try {
      const result = await getInventoryAlternatives(token, row.productId, row.branchId, superAdmin);
      setAlternatives(result.alternatives); setAlternativesMatchable(result.matchCriteriaAvailable);
    } catch (e) { setAlternatives([]); setAlternativesMatchable(true); toast.error(e instanceof Error ? e.message : "Possible alternatives could not be loaded."); }
    finally { setAlternativesLoading(false); }
  }

  useEntityRecord(masterRows, row => setMaster(row));
  function editMaster(row: InventoryProductMaster) { if (routeEntityEdit(row.id)) return; setMaster(row); }
  async function saveMaster() {
    if (!master) return;
    try { await updateInventoryProductMaster(token, master.id, { baseUnit: master.baseUnit, purchaseUnit: master.purchaseUnit, salesUnit: master.salesUnit, purchaseUnitToBase: master.purchaseUnitToBase, salesUnitToBase: master.salesUnitToBase, reorderLevel: master.reorderLevel, maximumStock: master.maximumStock, storageLocation: master.storageLocation, rackId: master.rackId || null, notes: master.notes, searchKeywords: master.searchKeywords, isActive: master.isActive, genericName: master.genericName, strength: master.strength, dosageForm: master.dosageForm, prescriptionRequired: master.prescriptionRequired, units: master.units.map((unit, index) => ({ ...unit, displayOrder: index })) }, superAdmin); toast.success("Medicine master updated."); setMaster(null); setMasterRows(await getInventoryProductMaster(token, masterSearch || undefined, superAdmin, branchId)); await loadOverview();  entitySaveComplete(); } catch (e) { toast.error(e instanceof Error ? e.message : "The medicine master could not be updated."); }
  }

  async function createCount() {
    const selectedBranch = branchId || branches.find((x) => x.isActive)?.id;
    if (!selectedBranch) return toast.error("Choose an active branch before starting a stock count.");
    try { const result = await createInventoryStockCount(token, { branchId: selectedBranch, search: search || undefined }, superAdmin); setActiveCount(result.id); setCountLines(result.lines.map((line) => ({ lineId: line.id, inventoryId: line.inventoryId, product: line.product, batchNumber: line.batchNumber, storageLocation: line.storageLocation, baseUnit: line.baseUnit, unitCost: line.unitCost, systemQuantity: line.systemQuantity, physicalQuantity: String(line.systemQuantity) }))); toast.success(`${result.countNumber} draft created. Enter physical quantities, then finalize it.`); setView("counts");  entitySaveComplete(); } catch (e) { toast.error(e instanceof Error ? e.message : "The stock count could not be created."); }
  }

  function finalizeCount() {
    if (!activeCount || countLines.some((line) => line.physicalQuantity === "" || Number(line.physicalQuantity) < 0)) return toast.error("Enter a valid physical quantity for every count line.");
    requestSiteConfirmation({ title: "Finalize this stock count?", message: "The confirmed physical quantities will become live stock. Variances will be posted to the movement ledger and cannot be edited afterward.", inputLabel: "Reason for the count / variance", inputPlaceholder: "For example, monthly count or damaged stock correction", inputRequired: true, confirmLabel: "Finalize count", tone: "danger", onConfirm: async (_checked, finalReason) => {
      try { await updateInventoryStockCountLines(token, activeCount, countLines.map((line) => ({ lineId: line.lineId, physicalQuantity: Number(line.physicalQuantity) })), superAdmin); const result = await finalizeInventoryStockCount(token, activeCount, finalReason?.trim(), superAdmin); toast.success(`Stock count finalized with ${result.totalVariance} units of variance.`); setActiveCount(""); setCountLines([]); await loadAuxiliary(); await loadOverview();  entitySaveComplete(); } catch (e) { toast.error(e instanceof Error ? e.message : "The stock count could not be finalized."); }
    } });
  }

  async function createAndDispatchTransfer() {
    const source = rows.find((row) => row.id === transferSource);
    if (!source || !transferTarget || Number(transferQuantity) <= 0) return toast.error("Choose a source batch, destination branch and quantity.");
    try { const created = await createInventoryTransfer(token, { sourceBranchId: source.branchId, targetBranchId: transferTarget, items: [{ inventoryId: source.id, quantity: Number(transferQuantity) }], note: transferNote.trim() || undefined }, superAdmin); await dispatchInventoryTransfer(token, created.id, superAdmin); toast.success(`${created.transferNumber} dispatched and source stock reduced.`); setTransferSource(""); setTransferTarget(""); setTransferQuantity("1"); setTransferNote(""); setView("transfers"); await loadAuxiliary(); await loadOverview();  entitySaveComplete(); } catch (e) { toast.error(e instanceof Error ? e.message : "The stock transfer could not be dispatched."); }
  }

  async function receiveTransfer(id: string) { try { await receiveInventoryTransfer(token, id, superAdmin); toast.success("Transfer received and destination stock increased."); await loadAuxiliary(); await loadOverview();  entitySaveComplete(); } catch (e) { toast.error(e instanceof Error ? e.message : "The transfer could not be received."); } }
  async function cancelTransfer(id: string) { try { await cancelInventoryTransfer(token, id, superAdmin); toast.success("Transfer cancelled and any dispatched stock was restored."); await loadAuxiliary(); await loadOverview();  entitySaveComplete(); } catch (e) { toast.error(e instanceof Error ? e.message : "The transfer could not be cancelled."); } }

  async function createPurchaseDraft(row: InventorySuggestion) {
    if (!row.supplierId) return toast.error("Add a preferred supplier to this product before creating a purchase draft.");
    if (row.purchaseUnitCost == null) return toast.error("A purchase cost is not available for this suggestion. Enter it in Purchase Department before creating a purchase order.");
    const multiplier = Math.max(1, row.purchaseUnitToBase || 1);
    const quantity = Math.ceil(row.suggestedOrderQuantity / multiplier);
    if (quantity <= 0) return toast.error("This product is already at or above its reorder level.");
    try {
      const order = await createAdminPurchaseOrder({ supplierId: row.supplierId, branchId: row.branchId, notes: "Draft created from the inventory reorder suggestion.", items: [{ productId: row.productId, quantity, unitCost: row.purchaseUnitCost ?? 0, unit: row.purchaseUnit || "piece" }] }, token, superAdmin);
      toast.success(`Draft purchase order ${order.orderNumber} created for ${quantity} ${row.purchaseUnit || "piece"}.`);
     entitySaveComplete(); } catch (e) { toast.error(e instanceof Error ? e.message : "The purchase draft could not be created."); }
  }

  function cancelCount(id: string) {
    requestSiteConfirmation({ title: "Cancel this stock count?", message: "The draft will be kept in history as cancelled, and no stock will be changed.", confirmLabel: "Cancel count", tone: "danger", onConfirm: async () => {
      try { await cancelInventoryStockCount(token, id, superAdmin); if (activeCount === id) { setActiveCount(""); setCountLines([]); } toast.success("Draft stock count cancelled."); await loadAuxiliary();  entitySaveComplete(); }
      catch (e) { toast.error(e instanceof Error ? e.message : "The stock count could not be cancelled."); }
    } });
  }

  const nav: [View, string, typeof Boxes][] = [["stock", "Live stock", Boxes], ["opening-stock", "Opening stock entry", Plus], ["master", "Medicine master", PackageSearch], ["movements", "Movement ledger", History], ["suggestions", "Purchase suggestions", Wand2], ["velocity", "Stock velocity", Activity], ["counts", "Stock counts", ClipboardCheck], ["transfers", "Branch transfers", ArrowRightLeft]];

  return <EntityListWorkspace title="Inventory"><div className="space-y-5">
    <div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-extrabold uppercase tracking-[0.16em] text-[#003893]">Inventory department</p><h2 className="mt-2 text-2xl font-extrabold">Pharmacy stock control</h2><p className="mt-1 text-sm text-slate-500">One batch-aware source of truth for FEFO, expiry, movements and branch stock.</p></div><Button variant="outline" onClick={() => void loadOverview()} disabled={loading}><RefreshCw size={15} className={loading ? "animate-spin" : ""} /> Refresh</Button></div>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{[["Active medicines", countsByStatus?.activeMedicines ?? 0], ["Available units", countsByStatus?.totalAvailableStock ?? 0], ["Stock value", countsByStatus?.stockValue == null ? "Restricted" : formatNPR(countsByStatus.stockValue)], ["Low stock", countsByStatus?.lowStock ?? 0], ["Out of stock", countsByStatus?.outOfStock ?? 0], ["Near expiry", countsByStatus?.nearExpiry ?? 0], ["Expired", countsByStatus?.expired ?? 0], ["Adjustments", countsByStatus?.stockAdjustments ?? 0], ["Pending transfers", countsByStatus?.pendingTransfers ?? 0], ["Non-moving", countsByStatus?.nonMoving ?? 0]].map(([label, value]) => <Card key={String(label)}><CardContent className="p-4"><p className="text-xs font-bold text-slate-500">{label}</p><p className="mt-2 text-2xl font-extrabold">{value}</p></CardContent></Card>)}</div>
    <div className="flex flex-wrap gap-2 rounded-2xl border bg-white p-2">{nav.map(([key, label, Icon]) => <Button key={key} size="sm" variant={view === key ? "default" : "ghost"} onClick={() => setView(key)}><Icon size={15} />{label}</Button>)}</div>
    {error && <p role="alert" className="rounded-xl bg-rose-50 p-4 text-sm font-semibold text-rose-700">{error}</p>}

    {view === "opening-stock" && <EntityFormPanel><form onSubmit={event => { event.preventDefault(); void saveOpeningStock(); }}><Card><CardHeader><CardTitle>Opening stock entry</CardTitle></CardHeader><CardContent className="space-y-4"><p className="text-sm text-slate-600">Record an existing physical batch as opening stock. This creates the batch balance, opening movement, and audit record together.</p><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3"><label className="space-y-1 text-xs font-bold text-slate-600">Product<Select value={openingProductId} onChange={(event) => { setOpeningProductId(event.target.value); setOpeningPurchasePrice(""); }}><option value="">Select active product</option>{masterRows.filter((product) => product.isActive).map((product) => <option key={product.id} value={product.id}>{product.name} · {product.productCode}</option>)}</Select></label><label className="space-y-1 text-xs font-bold text-slate-600">Branch<Select value={branchId || branches.find((branch) => branch.isActive)?.id || ""} disabled><option value="">Select branch</option>{branches.filter((branch) => branch.isActive).map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</Select></label><label className="space-y-1 text-xs font-bold text-slate-600">Batch number<Input value={openingBatch} onChange={(event) => setOpeningBatch(event.target.value)} maxLength={80} required /></label><label className="space-y-1 text-xs font-bold text-slate-600">Opening quantity (base units)<Input type="number" min="1" step="1" value={openingQuantity} onChange={(event) => setOpeningQuantity(event.target.value)} /></label><label className="space-y-1 text-xs font-bold text-slate-600">Purchase rate per base unit<Input type="number" min="0" step="0.01" value={openingPurchasePrice || masterRows.find((product) => product.id === openingProductId)?.purchaseRate || ""} onChange={(event) => setOpeningPurchasePrice(event.target.value)} /></label><label className="space-y-1 text-xs font-bold text-slate-600">Reference<Input value={openingReference} onChange={(event) => setOpeningReference(event.target.value)} maxLength={160} placeholder="Opening balance reference" /></label><label className="space-y-1 text-xs font-bold text-slate-600">Manufacturing date<Input type="date" value={openingManufactured} onChange={(event) => setOpeningManufactured(event.target.value)} /></label><label className="space-y-1 text-xs font-bold text-slate-600">Expiry date<Input type="date" value={openingExpiry} onChange={(event) => setOpeningExpiry(event.target.value)} /></label><label className="space-y-1 text-xs font-bold text-slate-600 md:col-span-2 xl:col-span-1">Reason<Input value={openingReason} onChange={(event) => setOpeningReason(event.target.value)} maxLength={500} required placeholder="Required audit reason" /></label></div>{!canWrite && <p role="alert" className="rounded-lg bg-amber-50 p-3 text-sm text-amber-800">Your role can view inventory but cannot post opening stock.</p>}<FormSaveActions mode="create" busy={!canWrite} onCancel={() => {}} /></CardContent></Card></form></EntityFormPanel>}

    {view === "opening-stock" && <EntityListPanel addLabel="Add opening stock" canAdd={canWrite}><MovementTable rows={movements} title="Opening stock register" /></EntityListPanel>}
    {view === "stock" && <><Card><CardContent className="flex flex-wrap items-end gap-3 p-4"><label className="min-w-64 flex-1 text-xs font-bold text-slate-500"><Search size={14} className="mr-1 inline" />Search medicine, generic, brand, barcode, code, batch, manufacturer or rack<Input value={search} onChange={(e) => { setPage(1); setSearch(e.target.value); }} className="mt-1" placeholder="Type to search live inventory" /></label><label className="text-xs font-bold text-slate-500">Near-expiry threshold<Select value={nearExpiryDays || String(overview?.nearExpiryDays ?? 90)} onChange={(e) => { setPage(1); setNearExpiryDays(e.target.value); }} className="mt-1"><option value="30">30 days</option><option value="60">60 days</option><option value="90">90 days</option><option value="180">180 days</option></Select></label>{canWrite && <Button variant="outline" onClick={() => void saveNearExpiryDefault()}>Save platform default</Button>}<Button variant={!filter ? "default" : "outline"} onClick={() => { setPage(1); setFilter(""); }}><SlidersHorizontal size={15} />All</Button><Button variant={filter === "LOW" ? "default" : "outline"} onClick={() => { setPage(1); setFilter("LOW"); }}>Low stock</Button><Button variant={filter === "OUT_OF_STOCK" ? "default" : "outline"} onClick={() => { setPage(1); setFilter("OUT_OF_STOCK"); }}>Out of stock</Button><Button variant={filter === "NEAR_EXPIRY" ? "default" : "outline"} onClick={() => { setPage(1); setFilter("NEAR_EXPIRY"); }}>Near expiry</Button><Button variant={filter === "EXPIRED" ? "default" : "outline"} onClick={() => { setPage(1); setFilter("EXPIRED"); }}>Expired</Button></CardContent></Card>{canWrite && selected && <Card className="border-[#003893]/20"><CardHeader><CardTitle>Controlled stock adjustment — {selected.product} / {selected.batchNumber}</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-[150px_180px_1fr_auto]"><Input type="number" value={delta} onChange={(e) => setDelta(e.target.value)} placeholder="+/- base units" /><Select value={adjustmentType} onChange={(e) => setAdjustmentType(e.target.value)}><option value="ADJUSTMENT">Correction</option><option value="DAMAGE">Damage</option><option value="EXPIRED">Expiry</option><option value="OPENING_STOCK">Opening stock</option><option value="OTHER">Other</option></Select><Input value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Required reason" /><div className="flex gap-2"><Button onClick={() => void saveAdjustment()}>Save</Button><Button variant="outline" onClick={() => setSelected(null)}>Cancel</Button></div></CardContent></Card>}<Card><CardHeader><CardTitle className="flex items-center gap-2"><Boxes size={18} className="text-[#003893]" />Batch-wise inventory <Badge variant="secondary" className="ml-auto">{overview?.totalRows ?? rows.length} batches</Badge></CardTitle></CardHeader><CardContent><div className="overflow-x-auto"><RecordTable className="w-full min-w-[1100px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wide text-slate-500"><th className="p-3">Medicine</th><th className="p-3">Batch / supplier</th><th className="p-3">Branch / rack</th><th className="p-3">Available</th><th className="p-3">Expiry</th><th className="p-3">Rate</th><th className="p-3">Status</th><th className="p-3" /></tr></thead><tbody>{rows.map((row) => { const key = `${row.productId}:${row.branchId}`; return <Fragment key={row.id}><tr className="border-b last:border-0"><td className="p-3 font-bold">{row.product}<span className="block text-xs font-normal text-slate-500">{row.genericName ?? row.brand ?? row.productCode}</span></td><td className="p-3">{row.batchNumber}<span className="block text-xs text-slate-500">{row.supplier ?? "Supplier not linked"}</span></td><td className="p-3">{row.branch}<span className="block text-xs text-slate-500">{row.storageLocation ?? "Rack not set"}</span></td><td className="p-3 font-extrabold">{row.availableQuantity} <span className="text-xs font-normal text-slate-500">{row.baseUnit}</span></td><td className="p-3">{row.expiryDate ? <>{formatPlatformDate(row.expiryDate)}<span className="block text-xs text-slate-500">{row.daysToExpiry ?? 0} days</span></> : "—"}</td><td className="p-3">{formatNPR(row.sellingPrice)}</td><td className="p-3"><Badge variant={statusTone(row.status)}>{row.status.replaceAll("_", " ")}</Badge></td><td className="p-3 text-right"><div className="flex justify-end gap-1">{canWrite && <Button size="sm" variant="ghost" onClick={() => setSelected(row)}><Plus size={15} />Adjust</Button>}<Button size="sm" variant="ghost" onClick={() => void toggleAlternatives(row)}>{alternativeKey === key ? "Hide alternatives" : "Alternatives"}</Button></div></td></tr>{alternativeKey === key && <tr className="border-b bg-slate-50"><td colSpan={8} className="p-4"><p className="mb-3 text-xs font-bold uppercase tracking-wide text-slate-600">Possible alternatives · matching generic, strength and dosage form; not a clinical substitution recommendation.</p>{alternativesLoading ? <p className="text-sm text-slate-500"><Loader2 size={14} className="mr-2 inline animate-spin" />Checking active catalog and branch stock…</p> : !alternativesMatchable ? <p className="text-sm text-slate-500">This medicine is missing generic, strength or dosage-form details, so a reliable match cannot be suggested.</p> : !alternatives?.length ? <p className="text-sm text-slate-500">No matching active medicines were found.</p> : <div className="grid gap-2 md:grid-cols-2">{alternatives.map((item) => <div key={item.productId} className="rounded-xl border bg-white p-3"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="font-bold">{item.name}{item.brand ? ` · ${item.brand}` : ""}</p><p className="mt-1 text-xs text-slate-500">{item.genericName} · {item.strength} · {item.dosageForm}</p></div><Badge variant={item.available > 0 ? "default" : "secondary"}>{item.available > 0 ? `${item.available} ${item.baseUnit} available` : "No eligible stock"}</Badge></div><p className="mt-2 text-xs text-slate-600">{formatNPR(item.sellingPrice)}{item.nearestExpiry ? ` · nearest expiry ${formatPlatformDate(item.nearestExpiry)}` : ""}</p>{item.batches.length > 0 && <p className="mt-1 text-xs text-slate-500">{item.batches.map((batch) => `${batch.batchNumber}: ${batch.available} · ${batch.expiryDate ? formatPlatformDate(batch.expiryDate) : "no expiry recorded"}`).join(" | ")}</p>}</div>)}</div>}</td></tr>}</Fragment>; })}{!rows.length && <tr><td colSpan={8} className="p-10 text-center text-slate-500">{loading ? <><Loader2 className="mr-2 inline animate-spin" size={16} />Loading live inventory…</> : "No inventory rows match this view."}</td></tr>}</tbody></RecordTable></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t pt-4 text-sm"><span className="text-slate-500">Page {overview?.page ?? page} of {Math.max(1, Math.ceil((overview?.totalRows ?? 0) / (overview?.pageSize ?? 100)))}</span><div className="flex gap-2"><Button variant="outline" size="sm" disabled={page <= 1 || loading} onClick={() => setPage((current) => Math.max(1, current - 1))}>Previous</Button><Button variant="outline" size="sm" disabled={page >= Math.ceil((overview?.totalRows ?? 0) / (overview?.pageSize ?? 100)) || loading} onClick={() => setPage((current) => current + 1)}>Next</Button></div></div></CardContent></Card></>}

    {view === "master" && <><Card><CardHeader><CardTitle>{setupTitle || "Medicine master"}</CardTitle></CardHeader><CardContent className="flex flex-wrap items-end gap-3 p-4"><p className="w-full text-sm text-slate-600">{setupTitle?.includes("Rack") ? "Assign structured rack-group and rack records to medicines; stock registers and physical counts use the same saved location." : "Search and manage the saved medicine master records used by stock and purchasing."}</p><label className="min-w-64 flex-1 text-xs font-bold text-slate-500">Search medicine master<Input value={masterSearch} onChange={(e) => setMasterSearch(e.target.value)} className="mt-1" placeholder="Name, generic, barcode, brand, manufacturer, category or rack" /></label><Button variant="outline" onClick={() => void loadAuxiliary()}><Search size={15} />Search</Button>{canManageMaster && !setupTitle?.includes("Rack") && <a href={superAdmin ? "/superadmin/products/create" : "/admin/products/create"} className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-[#003893] px-4 text-sm font-bold text-white transition hover:bg-[#002c72]"><Plus size={15} />Create product / medicine</a>}</CardContent></Card>{master && canManageMaster && <EntityFormPanel><MasterEditor master={master} setMaster={setMaster} racks={rackRows} onSave={() => void saveMaster()} onCancel={() => setMaster(null)} saving={false} rackOnly={!!setupTitle?.includes("Rack")} /></EntityFormPanel> }<EntityListPanel canAdd={false}><MasterTable rows={masterRows} onSelect={editMaster} canEdit={canManageMaster} title={setupTitle || "Medicine master"} rackOnly={!!setupTitle?.includes("Rack")} /></EntityListPanel></>}
    {view === "movements" && <><Card><CardHeader><CardTitle>{setupTitle || "Stock movement history"}</CardTitle></CardHeader><CardContent className="flex flex-wrap items-end gap-3 p-4"><label className="min-w-64 flex-1 text-xs font-bold text-slate-500">Medicine / product history<Select value={movementProductId} onChange={(event) => setMovementProductId(event.target.value)} className="mt-1"><option value="">All products in scope</option>{masterRows.map((product) => <option key={product.id} value={product.id}>{product.name} · {product.productCode}</option>)}</Select></label>{movementProductId && <Button variant="outline" onClick={() => setMovementProductId("")}>Clear product filter</Button>}</CardContent></Card><MovementTable rows={movements} title={setupTitle} /></>}
    {view === "suggestions" && <SuggestionTable rows={suggestions} canCreatePurchaseDraft={canCreatePurchaseDraft} onCreatePurchaseDraft={(row) => void createPurchaseDraft(row)} />}
    {view === "velocity" && <><Card><CardContent className="flex flex-wrap items-end gap-3 p-4"><label className="text-xs font-bold text-slate-500">Period<Select value={velocityDays} onChange={(e) => setVelocityDays(e.target.value)} className="mt-1"><option value="30">Last 30 days</option><option value="90">Last 90 days</option><option value="180">Last 180 days</option></Select></label><label className="text-xs font-bold text-slate-500">View<Select value={velocityFilter} onChange={(e) => setVelocityFilter(e.target.value)} className="mt-1"><option value="">All movement</option><option value="FAST_MOVING">Fast-moving</option><option value="SLOW_MOVING">Slow-moving</option><option value="NON_MOVING">Non-moving</option></Select></label></CardContent></Card><VelocityTable rows={velocity} /></>}
    {view === "counts" && <><Card><CardContent className="flex flex-wrap items-center justify-between gap-3 p-4"><div><p className="font-extrabold">Physical stock count</p><p className="text-sm text-slate-500">Create a draft, record physical quantities, then finalize approved variances.</p></div>{canWrite && <Button onClick={() => void createCount()}><ClipboardCheck size={15} />Start count</Button>}</CardContent></Card>{activeCount && <Card><CardHeader><CardTitle>Draft count — review batch quantities before posting</CardTitle></CardHeader><CardContent><div className="overflow-x-auto"><RecordTable className="w-full min-w-[820px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wide text-slate-500"><th className="p-3">Medicine / batch</th><th className="p-3">System qty</th><th className="p-3">Physical qty</th><th className="p-3">Variance</th><th className="p-3">Variance value</th></tr></thead><tbody>{countLines.map((line) => { const physical = Number(line.physicalQuantity); const variance = Number.isFinite(physical) ? physical - line.systemQuantity : 0; return <tr key={line.lineId} className="border-b last:border-0"><td className="p-3 font-bold">{line.product}<span className="block text-xs font-normal text-slate-500">{line.batchNumber} · {line.storageLocation || "Rack not set"}</span></td><td className="p-3">{line.systemQuantity} {line.baseUnit}</td><td className="p-3"><Input className="w-32" type="number" min="0" step="1" value={line.physicalQuantity} onChange={(e) => setCountLines((current) => current.map((item) => item.lineId === line.lineId ? { ...item, physicalQuantity: e.target.value } : item))} aria-label={`Physical quantity for ${line.product}, batch ${line.batchNumber}`} /></td><td className={`p-3 font-bold ${variance < 0 ? "text-rose-700" : variance > 0 ? "text-emerald-700" : ""}`}>{variance > 0 ? "+" : ""}{variance} {line.baseUnit}</td><td className="p-3">{line.unitCost == null ? "Restricted" : formatNPR(variance * line.unitCost)}</td></tr>; })}{!countLines.length && <tr><td colSpan={5} className="p-8 text-center text-slate-500">No stock batches were found for this count.</td></tr>}</tbody></RecordTable></div><Button className="mt-4" onClick={finalizeCount}>Finalize count</Button></CardContent></Card>}<CountTable rows={counts} canWrite={canWrite} onCancel={cancelCount} /></>}
    {view === "transfers" && <><EntityFormPanel><form onSubmit={event => { event.preventDefault(); void createAndDispatchTransfer(); }}><Card><CardHeader><CardTitle className="flex items-center gap-2"><Truck size={18} className="text-[#003893]" />Dispatch stock to another branch</CardTitle></CardHeader><CardContent className="grid gap-3 md:grid-cols-[1.5fr_1fr_120px_1fr_auto]"><Select value={transferSource} onChange={(e) => setTransferSource(e.target.value)}><option value="">Select source batch</option>{rows.filter((row) => row.availableQuantity > 0 && ["IN_STOCK", "LOW_STOCK", "NEAR_EXPIRY"].includes(row.status)).map((row) => <option key={row.id} value={row.id}>{row.product} · {row.batchNumber} · {row.availableQuantity} available</option>)}</Select><Select value={transferTarget} onChange={(e) => setTransferTarget(e.target.value)}><option value="">Destination branch</option>{branches.filter((branch) => branch.isActive && branch.id !== branchId).map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</Select><Input type="number" min="1" value={transferQuantity} onChange={(e) => setTransferQuantity(e.target.value)} /><Input value={transferNote} onChange={(e) => setTransferNote(e.target.value)} placeholder="Transfer reason" /><FormSaveActions mode="create" busy={!canTransfer} onCancel={() => {}} /></CardContent></Card></form></EntityFormPanel><EntityListPanel addLabel="Add transfer" canAdd={canWrite}><TransferTable rows={transferRows} canReceive={canWrite} onReceive={(id) => void receiveTransfer(id)} onCancel={(id) => void cancelTransfer(id)} /></EntityListPanel></>}
  </div></EntityListWorkspace>;
}

function MasterEditor({ master, setMaster, racks, onSave, onCancel, saving, rackOnly = false }: { master: InventoryProductMaster; setMaster: (value: InventoryProductMaster) => void; racks: ProductRack[]; onSave: () => void; onCancel: () => void; saving: boolean; rackOnly?: boolean }) { const field = (key: keyof InventoryProductMaster, value: string | number | boolean | null) => setMaster({ ...master, [key]: value }); return <Card className="border-[#003893]/20"><CardHeader><CardTitle>{rackOnly ? "Rack location — " : "Medicine master — "}{master.name}</CardTitle></CardHeader><CardContent className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{!rackOnly && <><div><Label>Base unit</Label><Input value={master.baseUnit} onChange={(e) => field("baseUnit", e.target.value)} /></div><div><Label>Purchase unit</Label><Input value={master.purchaseUnit} onChange={(e) => field("purchaseUnit", e.target.value)} /></div><div><Label>Sales unit</Label><Input value={master.salesUnit} onChange={(e) => field("salesUnit", e.target.value)} /></div><div><Label>Purchase → base</Label><Input type="number" min="1" value={master.purchaseUnitToBase} onChange={(e) => field("purchaseUnitToBase", Number(e.target.value))} /></div><div><Label>Sales → base</Label><Input type="number" min="1" value={master.salesUnitToBase} onChange={(e) => field("salesUnitToBase", Number(e.target.value))} /></div><div><Label>Reorder level</Label><Input type="number" min="0" value={master.reorderLevel} onChange={(e) => field("reorderLevel", Number(e.target.value))} /></div><div><Label>Maximum stock</Label><Input type="number" min="0" value={master.maximumStock} onChange={(e) => field("maximumStock", Number(e.target.value))} /></div></>}<div className={rackOnly ? "sm:col-span-2" : ""}><Label>Product rack</Label><Select value={master.rackId ?? ""} onChange={(e) => field("rackId", e.target.value || null)}><option value="">{racks.length ? "Legacy / unassigned location" : "No active racks configured"}</option>{racks.map((rack) => <option key={rack.id} value={rack.id}>{rack.rackGroup} · {rack.name}</option>)}</Select></div>{(!rackOnly || !master.rackId) && <div><Label>{rackOnly ? "Legacy shelf / cell location" : "Legacy rack / shelf / cell"}</Label><Input value={master.storageLocation ?? ""} onChange={(e) => field("storageLocation", e.target.value)} placeholder="e.g. G1 / R02 / S03" /></div>}{!rackOnly && <div className="sm:col-span-2 lg:col-span-4"><Label>Generic, substitute or alternate search terms</Label><Input value={master.searchKeywords ?? ""} onChange={(e) => field("searchKeywords", e.target.value)} placeholder="Comma-separated generic or substitute names" /></div>}<div className="sm:col-span-2 lg:col-span-4 flex gap-2"><Button onClick={onSave} disabled={saving}><Check size={15} />{rackOnly ? "Save rack location" : "Save master"}</Button><Button variant="outline" onClick={onCancel}>Cancel</Button></div></CardContent></Card>; }
function MasterTable({ rows, onSelect, canEdit, title = "Medicine master", rackOnly = false }: { rows: InventoryProductMaster[]; onSelect: (row: InventoryProductMaster) => void; canEdit: boolean; title?: string; rackOnly?: boolean }) { return <Card><CardHeader><CardTitle className="flex items-center gap-2"><PackageSearch size={18} className="text-[#003893]" />{title}</CardTitle></CardHeader><CardContent><div className="overflow-x-auto"><RecordTable className="w-full min-w-[750px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wide text-slate-500"><th className="p-3">Medicine</th>{!rackOnly && <><th className="p-3">Generic / brand</th><th className="p-3">Units</th><th className="p-3">Reorder</th></>}<th className="p-3">Rack group / rack / shelf / cell</th><th className="p-3">Stock</th><th className="p-3" /></tr></thead><tbody>{rows.map((row) => <tr key={row.id} className="border-b last:border-0"><td className="p-3 font-bold">{row.name}<span className="block text-xs font-normal text-slate-500">{row.productCode} · {row.barcode ?? "No barcode"}</span></td>{!rackOnly && <><td className="p-3">{row.genericName ?? "—"}<span className="block text-xs text-slate-500">{row.brand ?? row.manufacturer ?? "—"}</span></td><td className="p-3">{row.baseUnit} · {row.salesUnit} × {row.salesUnitToBase}</td><td className="p-3">{row.reorderLevel} / {row.maximumStock || "—"}</td></>}<td className="p-3">{row.storageLocation ?? "—"}</td><td className="p-3 font-bold">{row.stock}</td><td className="p-3 text-right">{canEdit && <Button size="sm" variant="outline" onClick={() => onSelect(row)}>Edit</Button>}</td></tr>)}{!rows.length && <tr><td colSpan={rackOnly ? 4 : 7} className="p-8 text-center text-slate-500">No medicines found.</td></tr>}</tbody></RecordTable></div></CardContent></Card>; }
function MovementTable({ rows, title = "Stock movement ledger" }: { rows: InventoryMovement[]; title?: string }) { return <Card><CardHeader><CardTitle className="flex items-center gap-2"><History size={18} className="text-[#003893]" />{title || "Stock movement ledger"}</CardTitle></CardHeader><CardContent><div className="overflow-x-auto"><RecordTable className="w-full min-w-[1000px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wide text-slate-500"><th className="p-3">Date</th><th className="p-3">Medicine / batch</th><th className="p-3">Branch</th><th className="p-3">Movement</th><th className="p-3">Before</th><th className="p-3">Change</th><th className="p-3">After</th><th className="p-3">Reason</th></tr></thead><tbody>{rows.map((row) => <tr key={row.id} className="border-b last:border-0"><td className="p-3 whitespace-nowrap">{formatPlatformDateTime(row.date)}</td><td className="p-3 font-bold">{row.product}<span className="block text-xs font-normal text-slate-500">{row.batch}</span></td><td className="p-3">{row.branch}</td><td className="p-3"><Badge variant="secondary">{row.type.replaceAll("_", " ")}</Badge></td><td className="p-3">{row.quantityBefore}</td><td className={`p-3 font-bold ${row.quantity < 0 ? "text-rose-700" : "text-emerald-700"}`}>{row.quantity > 0 ? "+" : ""}{row.quantity}</td><td className="p-3">{row.quantityAfter}</td><td className="p-3">{row.reason ?? row.note ?? "—"}</td></tr>)}{!rows.length && <tr><td colSpan={8} className="p-8 text-center text-slate-500">No movement history found.</td></tr>}</tbody></RecordTable></div></CardContent></Card>; }
function SuggestionTable({ rows, canCreatePurchaseDraft, onCreatePurchaseDraft }: { rows: InventorySuggestion[]; canCreatePurchaseDraft: boolean; onCreatePurchaseDraft: (row: InventorySuggestion) => void }) {
  return <Card><CardHeader><CardTitle className="flex items-center gap-2"><Wand2 size={18} className="text-[#003893]" />Purchase suggestions</CardTitle></CardHeader><CardContent><div className="overflow-x-auto"><RecordTable className="w-full min-w-[900px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wide text-slate-500"><th className="p-3">Medicine</th><th className="p-3">Branch</th><th className="p-3">Available</th><th className="p-3">Incoming PO qty</th><th className="p-3">Reorder / max</th><th className="p-3">Suggested order</th><th className="p-3">Supplier</th><th className="p-3" /></tr></thead><tbody>{rows.map((row) => <tr key={`${row.productId}-${row.branchId}`} className="border-b last:border-0"><td className="p-3 font-bold">{row.product}<span className="block text-xs font-normal text-slate-500">{row.sku}</span></td><td className="p-3">{row.branch}</td><td className="p-3">{row.available}</td><td className="p-3">{row.pendingPurchaseQuantity}</td><td className="p-3">{row.reorderLevel} / {row.maximumStock}</td><td className="p-3 font-extrabold text-[#003893]">{Math.ceil(row.suggestedOrderQuantity / Math.max(1, row.purchaseUnitToBase || 1))} {row.purchaseUnit || "piece"}</td><td className="p-3">{row.supplier ?? "No preferred supplier"}</td><td className="p-3 text-right">{canCreatePurchaseDraft && <Button size="sm" variant="outline" disabled={!row.supplierId || row.suggestedOrderQuantity <= 0 || row.purchaseUnitCost == null} onClick={() => onCreatePurchaseDraft(row)} title={!row.supplierId ? "A preferred supplier is required" : row.purchaseUnitCost == null ? "A known purchase cost is required to create a draft" : "Create a draft purchase order for review"}>Create draft PO</Button>}</td></tr>)}{!rows.length && <tr><td colSpan={8} className="p-8 text-center text-slate-500">No reorder suggestions from current stock.</td></tr>}</tbody></RecordTable></div><p className="mt-3 text-xs text-slate-500">Suggestions account for valid stock and outstanding sent/partially received purchase orders. Drafts are not sent to suppliers automatically.</p></CardContent></Card>;
}
function VelocityTable({ rows }: { rows: InventoryVelocity[] }) { return <Card><CardHeader><CardTitle className="flex items-center gap-2"><Activity size={18} className="text-[#003893]" />Fast, slow and non-moving stock</CardTitle></CardHeader><CardContent><div className="overflow-x-auto"><RecordTable className="w-full min-w-[800px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wide text-slate-500"><th className="p-3">Medicine</th><th className="p-3">Classification</th><th className="p-3">Sold</th><th className="p-3">Current stock</th><th className="p-3">Stock value</th><th className="p-3">Last sale</th></tr></thead><tbody>{rows.map((row) => <tr key={row.productId} className="border-b last:border-0"><td className="p-3 font-bold">{row.product}</td><td className="p-3"><Badge variant={row.classification === "FAST_MOVING" ? "default" : "secondary"}>{row.classification.replaceAll("_", " ")}</Badge></td><td className="p-3">{row.quantitySold}</td><td className="p-3">{row.currentStock}</td><td className="p-3">{row.stockValue == null ? "Restricted" : formatNPR(row.stockValue)}</td><td className="p-3">{row.lastSaleDate ? formatPlatformDate(row.lastSaleDate) : "No sale in period"}</td></tr>)}{!rows.length && <tr><td colSpan={6} className="p-8 text-center text-slate-500">No sales history is available for this period.</td></tr>}</tbody></RecordTable></div></CardContent></Card>; }
function CountTable({ rows, canWrite, onCancel }: { rows: InventoryStockCount[]; canWrite: boolean; onCancel: (id: string) => void }) { return <Card><CardHeader><CardTitle className="flex items-center gap-2"><ClipboardCheck size={18} className="text-[#003893]" />Stock count history</CardTitle></CardHeader><CardContent><div className="overflow-x-auto"><RecordTable className="w-full min-w-[760px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wide text-slate-500"><th className="p-3">Count</th><th className="p-3">Branch</th><th className="p-3">Created</th><th className="p-3">Lines</th><th className="p-3">Variance</th><th className="p-3">Status</th><th className="p-3" /></tr></thead><tbody>{rows.map((row) => <tr key={row.id} className="border-b last:border-0"><td className="p-3 font-bold">{row.countNumber}</td><td className="p-3">{row.branch}</td><td className="p-3">{formatPlatformDate(row.createdAt)}</td><td className="p-3">{row.lineCount}</td><td className="p-3">{row.variance} / {row.varianceValue == null ? "Restricted" : formatNPR(row.varianceValue)}</td><td className="p-3"><Badge variant={row.status === "FINALIZED" ? "default" : row.status === "CANCELLED" ? "destructive" : "secondary"}>{row.status}</Badge></td><td className="p-3 text-right">{canWrite && row.status === "DRAFT" && <Button size="sm" variant="outline" onClick={() => onCancel(row.id)}>Cancel draft</Button>}</td></tr>)}{!rows.length && <tr><td colSpan={7} className="p-8 text-center text-slate-500">No stock counts created yet.</td></tr>}</tbody></RecordTable></div></CardContent></Card>; }
function TransferTable({ rows, canReceive, onReceive, onCancel }: { rows: InventoryTransfer[]; canReceive: boolean; onReceive: (id: string) => void; onCancel: (id: string) => void }) { return <Card><CardHeader><CardTitle className="flex items-center gap-2"><ArrowRightLeft size={18} className="text-[#003893]" />Transfer history</CardTitle></CardHeader><CardContent><div className="overflow-x-auto"><RecordTable className="w-full min-w-[900px] text-left text-sm"><thead><tr className="border-b text-xs uppercase tracking-wide text-slate-500"><th className="p-3">Transfer</th><th className="p-3">Route</th><th className="p-3">Items</th><th className="p-3">Created</th><th className="p-3">Status</th><th className="p-3" /></tr></thead><tbody>{rows.map((row) => <tr key={row.id} className="border-b last:border-0"><td className="p-3 font-bold">{row.transferNumber}</td><td className="p-3">{row.sourceBranch} → {row.targetBranch}</td><td className="p-3">{row.items.reduce((sum, item) => sum + item.quantity, 0)} units</td><td className="p-3">{formatPlatformDate(row.createdAt)}</td><td className="p-3"><Badge variant={row.status === "RECEIVED" ? "default" : row.status === "CANCELLED" ? "destructive" : "secondary"}>{row.status.replaceAll("_", " ")}</Badge></td><td className="p-3 text-right"><div className="flex justify-end gap-2">{canReceive && row.status === "IN_TRANSIT" && <Button size="sm" onClick={() => onReceive(row.id)}><Check size={15} />Receive</Button>}{canReceive && row.status !== "RECEIVED" && row.status !== "CANCELLED" && <Button size="sm" variant="outline" onClick={() => onCancel(row.id)}>Cancel</Button>}</div></td></tr>)}{!rows.length && <tr><td colSpan={6} className="p-8 text-center text-slate-500">No branch transfers found.</td></tr>}</tbody></RecordTable></div></CardContent></Card>; }
